{"path": "simple_linked_list.py", "content": "class EmptyListException(Exception):
    """Exception raised when the linked list is empty.

    message: explanation of the error.
    """

    def __init__(self, message):
        super().__init__(message)
        self.message = message


class Node:
    def __init__(self, value, next_node=None):
        self._value = value
        self._next = next_node

    def value(self):
        return self._value

    def next(self):
        return self._next


class LinkedList:
    def __init__(self, values=None):
        self._head = None
        self._length = 0
        for value in values or []:
            self.push(value)

    def __iter__(self):
        current = self._head
        while current is not None:
            yield current.value()
            current = current.next()

    def __len__(self):
        return self._length

    def head(self):
        if self._head is None:
            raise EmptyListException("The list is empty.")
        return self._head

    def push(self, value):
        self._head = Node(value, self._head)
        self._length += 1

    def pop(self):
        if self._head is None:
            raise EmptyListException("The list is empty.")
        node = self._head
        self._head = node.next()
        self._length -= 1
        return node.value()

    def reversed(self):
        # Iteration yields head-first; pushing in that order reverses the list.
        return LinkedList(self)
